const START_SERVICE={'madrid-barcelona':[.25,'s112'],'madrid-valencia':[.3,'s103'],'madrid-sevilla':[.3,'s100'],'madrid-malaga':[.25,'s112'],'madrid-alicante':[.3,'s103'],'madrid-santander':[.5,'s130'],'madrid-pamplona':[.4,'s130'],'madrid-badajoz':[.35,'s730']};
const maxFrequency=r=>r.real?r.baseFrequency:12;
/** Índice de costes: energía, personal y canon suben cada año; las tarifas, solo si las sube el jugador. */
const costIndex=s=>1+.0205*Math.max(0,economicYear(s)-2022);
function initialState(seed=72022){
 const s={version:4,tycoon:T.initialTycoon(),stations:{},requests:[],month:0,seed,cash:500,debt:0,reputation:50,satisfaction:58,policy:'public',started:false,ended:false,maintenance:1,chapter:0,claimed:[],decided:[],flags:{},history:[],log:[],orders:[],projects:[],refits:[],routes:copy(ALL_ROUTES),fleet:[],infra:I.initialInfra(),nextId:20,stats:{requests:0,refurbished:0,purchased:0,delivered:0,upgrades:0,built:0,passengers:0},last:{revenue:0,cost:0,subsidy:0,net:0,passengers:0},seen:[],event:null,events:[]};
 [['s100',12,56,1992],['s112',22,78,2010],['s103',16,82,2007],['s130',14,72,2008],['s730',8,74,2012],['s120',8,64,2006]].forEach(([model,qty,condition,born],i)=>s.fleet.push({id:'f'+i,model,qty,condition,born,origin:'Parque inicial'}));
 for(const r of s.routes){const st=START_SERVICE[r.id];if(!st)continue;const f=s.fleet.find(f=>f.model===st[1]);if(!routeCheck(s,r,MODEL[f.model]).ok)continue;r.active=true;r.fleet=f.id;r.frequency=Math.max(1,Math.round(maxFrequency(r)*st[0]));r.units=requiredUnits(s,r,MODEL[f.model],r.frequency);}
 historic(s);T.offer(s);generateRequest(s,true);generateRequest(s,true);log(s,'Te sientas en el despacho','Ocho servicios funcionan a medio gas. El resto de la red espera trenes, obras o que alguien se acuerde de ella.');return s;
}
function random(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
function log(s,title,body){s.log.unshift({month:effectiveMonth(s),title,body});s.log=s.log.slice(0,100);}
// ---- Red: qué puede circular por cada relación
/** Recorrido de la relación con un modelo de tren: tiempo, kilómetros, cambios de ancho y, si no puede, qué falta. */
function routeCheck(s,r,m){return I.plan(s,r.via,I.profileOf(m));}
/** Lo que permite la red para AVE, Alvia eléctrico y Alvia híbrido. */
function routeOptions(s,r){return {ave:I.plan(s,r.via,I.PROFILES.ave),alvia:I.plan(s,r.via,I.PROFILES.alvia),hybrid:I.plan(s,r.via,I.PROFILES.hybrid)};}
const canRun=(s,r,m)=>!!m&&routeCheck(s,r,m).ok;
function isUnlocked(s,r){const o=routeOptions(s,r);return o.ave.ok||o.alvia.ok||o.hybrid.ok;}
function product(s,r){const f=r.fleet&&s.fleet.find(f=>f.id===r.fleet);return f?MODEL[f.model].family:null;}
/** Mejor producto posible hoy: AVE si la red lo permite; si no, Alvia. */
function bestProduct(s,r){const o=routeOptions(s,r);return o.ave.ok?'AVE':o.alvia.ok||o.hybrid.ok?'Alvia':null;}
function requiredUnits(s,r,m,f){
 return T.requiredUnits(s,r,m,f);
}
const available=(s,f,except=null)=>f.qty-s.routes.filter(r=>r.active&&r.fleet===f.id&&r.id!==except).reduce((n,r)=>n+r.units,0);
function metrics(s,r,override={}){
 r={...r,...override};const f=s.fleet.find(f=>f.id===r.fleet),m=f&&MODEL[f.model];
 if(!r.active||!m)return {passengers:0,revenue:0,cost:0,subsidy:0,net:0,occupancy:0,share:0,punctuality:0,trainTime:0,busShare:.62,otherShare:.38};
 const p=routeCheck(s,r,m),km=r.real?r.km:(p.km||r.km),pathMin=p.ok?p.minutes:km/1.5;
 const tx=T.effects(s,r);
 const trainTime=Math.max(.2,((r.real&&r.minutes?(r.minutes+pathMin)/2:pathMin)/60+.1)*tx.speed-(p.changes?.length||0)*tx.changer/60),busTime=km/73+.5;
 const year=yearOf(s),season=1+.10*Math.sin(s.month/12*Math.PI*2),recovery=Math.min(1.25,.72+s.month*.009);
 const growth=1+Math.min(.55,(year-2022)*.012),ave=m.family==='AVE';
 const stationBoost=1+.06*((s.stations?.[r.ends[0]]||0)+(s.stations?.[r.ends[1]]||0));
 const on=k=>s.flags[k]>s.month,demand=r.demand*recovery*growth*season*stationBoost*tx.demand*(ave?1.15:1)*(on('passes')&&!ave?1.15:1)*(on('hype')&&ave?1.1:1)*(on('tourism')?1.1:1);
 const reliability=clamp(67+tx.quality+f.condition*.29+(s.maintenance-1)*7+r.level*2+(stationBoost-1)*12-(p.changes?.length||0)*1.5-(on('strike')?10:0)-(on('heat')?5:0),50,99);
 const rivals=T.competition(s,r);
 const rivalWeight=rivals.reduce((n,c)=>n+Math.exp(clamp(1.6-trainTime*.2-c.fare/35+c.frequency*.045+(c.quality-80)*.018,-3,4))*.16,0);
 const busFare=Math.max(4,km*.066)*(s.flags.buswar>s.month?.78:1);
 const trainWeight=Math.exp(clamp(1.6-trainTime*.2-r.fare*tx.fare/35+Math.min(r.frequency,40)*.045+(reliability-80)*.018+(s.reputation-50)*.012+r.level*.12,-3,4));
 const busWeight=Math.exp(clamp(1.1-busTime*.2-busFare/35,-3,4));
 const otherWeight=.33+rivalWeight,weight=trainWeight+busWeight+otherWeight;
 const share=trainWeight/weight,capacity=m.seats*r.frequency*2*30*tx.staff;
 const passengers=Math.round(Math.min(capacity*.98,demand*share)),revenue=passengers*r.fare*tx.fare*(tx.refund?1-(100-reliability)*.0005:1)/1e6;
 // Coste por tren-km: energía (el híbrido quema gasóleo), personal, canon y mantenimiento (parámetros de juego).
 const energy=(s.flags.energy>s.month?1.22:1),trainKm=r.frequency*2*30*km,operating=trainKm*(m.energy*2.8*energy+(ave?17:12))*costIndex(s)/1e6;
 const cost=operating*tx.cost*(m.power==='hybrid'&&s.tycoon.tech.includes('hydrogen')?.92:1)+r.units*.03*s.maintenance+.06+r.level*.025;
 const subsidy=ave?0:trainKm*(s.policy==='public'?2.2:1.6)/1e6+.04;
 return {passengers,revenue,cost,subsidy,net:revenue+subsidy-cost,occupancy:capacity?passengers/capacity:0,share,punctuality:reliability,trainTime,busShare:busWeight/weight,otherShare:otherWeight/weight};
}
function balance(s){
 const parts=s.routes.filter(r=>r.active).map(r=>metrics(s,r));
 const sum=k=>parts.reduce((n,p)=>n+p[k],0),passengers=sum('passengers');
 const overhead=(9+s.fleet.reduce((n,f)=>n+f.qty*.035,0))*costIndex(s)+s.debt*.004;
 const subsidy=sum('subsidy')+(s.policy==='public'?3.5:2)+(s.flags.rural>s.month?6:0);
 const cost=sum('cost')+overhead+T.monthlyCost(s),revenue=sum('revenue');
 return {passengers,revenue,cost,subsidy,net:revenue+subsidy-cost,punctuality:parts.length?sum('punctuality')/parts.length:0,share:parts.length?sum('share')/parts.length:0};
}
function configureRoute(s,id,fleetId,frequency,fare){
 ensurePlaying(s);const r=s.routes.find(x=>x.id===id),f=s.fleet.find(x=>x.id===fleetId);
 if(!r||!f)throw Error('Elige una relación y un tren, que no es tan difícil.');
 const m=MODEL[f.model];frequency=Number(frequency);fare=Number(fare);
 if(!Number.isInteger(frequency)||frequency<1||frequency>maxFrequency(r)||!Number.isFinite(fare)||fare<1.5||fare>150)throw Error(`Entre 1 y ${maxFrequency(r)} salidas por sentido, y una tarifa de 1,5 a 150 €.`);
 const p=routeCheck(s,r,m);
 if(!p.ok)throw Error(`El ${m.family} no puede ir por ahí: ${I.faultText(s,p.faults[0]).toLowerCase()}.`);
 if(f.condition<30)throw Error('Este tren está para el desguace. Mándalo al taller antes de sacarlo.');
 const units=requiredUnits(s,r,m,frequency);
 if(available(s,f,r.id)<units)throw Error(`Necesitas ${units} trenes y en ese lote solo quedan ${available(s,f,r.id)} libres.`);
 const opening=!r.active;if(opening&&s.cash<4)throw Error('Ni para los 4 M€ de la reapertura llega la caja.');
 if(opening)s.cash-=4;Object.assign(r,{fleet:fleetId,frequency,fare,units,active:true});delete r.cut;
 if(opening)log(s,'Servicio en marcha',routeName(r)+' · '+m.family);return r;
}
function closeRoute(s,id){ensurePlaying(s);const r=s.routes.find(r=>r.id===id);if(!r||!r.active)throw Error('Ese servicio ya está cerrado.');r.active=false;r.fleet=null;r.units=0;s.reputation=clamp(s.reputation-1,5,100);log(s,'Servicio suspendido',routeName(r));}
function upgradeRoute(s,id){ensurePlaying(s);const r=s.routes.find(r=>r.id===id);if(!r||r.level>=3)throw Error('Ya está al máximo. Más no se puede.');if(s.projects.some(p=>p.id==='upgrade-'+id&&!p.done))throw Error('La mejora ya está en marcha.');const cost=12+12*r.level;spend(s,cost);s.projects.push({id:'upgrade-'+id,type:'upgrade',route:id,due:s.month+4,started:s.month,cost,done:false});log(s,'Mejora contratada',routeName(r)+' · información, accesibilidad y fiabilidad.');}
function purchaseQuote(s,model,qty,listing=null){
 const m=MODEL[model];qty=Number(qty);if(!m||!Number.isInteger(qty)||qty<1||qty>30)throw Error('Entre 1 y 30 unidades.');
 const price=m.price*(1+Math.max(0,economicYear(s)-2022)*.018),total=price*qty;
 const backlog=s.orders.filter(o=>!o.historical&&o.marketplace?.state!=='used'&&o.delivered<o.qty).reduce((n,o)=>n+o.qty-o.delivered,0);
 const lead=Math.max(16,m.lead+Math.floor(backlog/10)*2+(s.flags.backlog>s.month?8:0)-(s.flags.factory>s.month?6:0));
 const standard={total,deposit:total*.3,remaining:total*.7,lead,last:lead+Math.ceil(qty/2)-1,unit:price};
 return listing?M.quoteListing(s,model,qty,listing,standard):standard;
}
function buy(s,model,qty,listing=null){
 ensurePlaying(s);if(!MODEL[model]||!listing&&yearOf(s)<MODEL[model].year)throw Error('Ese modelo todavía no se vende.');
 const q=purchaseQuote(s,model,qty,listing);qty=Number(qty);spend(s,q.deposit);
 const id='o'+s.nextId++,o={id,model,qty,delivered:0,start:s.month,first:s.month+q.lead,next:s.month+q.lead,total:q.total,remaining:q.remaining,unit:q.unit,delay:0,historical:false};
 if(q.item){const item=q.item;o.marketplace={listing:item.id,state:item.state,maker:item.maker,condition:item.condition,born:yearOf(s)-item.age,depositRate:q.depositRate};if(item.state==='used'){const market=M.ensureMarketplace(s);market.sold[item.id]=(market.sold[item.id]||0)+qty;o.delayChecked=true;}}
 s.orders.push(o);s.stats.purchased+=qty;
 if(q.lead===0){o.delivered=qty;addPurchasedFleet(s,o,qty);s.stats.delivered+=qty;log(s,'Compra en Trenespop',`${qty} × ${MODEL[model].name} · ${o.marketplace.condition} % de estado. Ya están en tu parque.`);}
 else log(s,q.item?'Compra en Trenespop':'Pedido firmado',`${qty} × ${MODEL[model].name}${q.item?' · '+q.item.maker:''}. Primera entrega: ${dateOf(s.month+q.lead)}${q.item?.state==='used'?'.':', si el fabricante quiere.'}`);
 return id;
}
function marketplaceFavorite(s,listing){return M.favorite(s,listing);}
function refurbish(s,id,qty){ensurePlaying(s);const f=s.fleet.find(f=>f.id===id);qty=Number(qty);if(!f||!Number.isInteger(qty)||qty<1||available(s,f)<qty)throw Error('Solo se reforman trenes libres del lote.');spend(s,qty*MODEL[f.model].price*.12);f.qty-=qty;s.refits.push({id:'ref'+s.nextId++,model:f.model,qty,due:s.month+5,born:f.born});log(s,'Al taller',qty+' × '+MODEL[f.model].name+' · 5 meses.');}
function sell(s,id,qty){ensurePlaying(s);const f=s.fleet.find(f=>f.id===id);qty=Number(qty);if(!f||!Number.isInteger(qty)||qty<1||available(s,f)<qty)throw Error('Solo se venden trenes libres.');const value=qty*MODEL[f.model].price*.23*(f.condition/100);s.cash+=value;f.qty-=qty;log(s,'Venta de material',qty+' × '+MODEL[f.model].name+' · '+value.toFixed(1)+' M€.');}
// ---- Obras
function startProject(s,id){ensurePlaying(s);const p=PROJECTS.find(p=>p.id===id);if(!p)throw Error('Proyecto desconocido.');if(s.projects.some(x=>x.id===id))throw Error('Ese proyecto ya está contratado.');spend(s,p.cost);const due=Math.max(s.month+p.duration,(p.earliest-2022)*12);s.projects.push({id,type:'infrastructure',started:s.month,due,originalDue:due,cost:p.cost,done:false,delay:0});log(s,'Obra adjudicada',p.name+' · fin previsto: '+dateOf(due));}
/** ¿Usa este servicio el tramo con su tren actual? */
function routeUses(s,r,tramo){const f=s.fleet.find(f=>f.id===r.fleet);return !!f&&routeCheck(s,r,MODEL[f.model]).tramos.some(t=>t.id===tramo);}
const worksDiscount=s=>s.flags.eufunds>s.month?.6:1;
function workQuote(s,kind,target){
 if(kind==='changer'){if(!I.changerPossible(s,target))throw Error('Ahí no pinta nada un cambiador de ancho.');if(s.projects.some(p=>!p.done&&p.type==='changer'&&p.target===target))throw Error('Ya se está construyendo.');return {cost:Math.round(I.CHANGER_WORK.cost*worksDiscount(s)),months:I.CHANGER_WORK.months,closes:false,affected:[],label:I.CHANGER_WORK.label};}
 const w=I.tramoWorks(s,target).find(x=>x.work===kind);
 if(!w)throw Error('Esa obra no tiene sentido en este tramo.');if(w.busy)throw Error('Ya hay máquinas trabajando en este tramo.');
 const affected=w.closes?s.routes.filter(r=>r.active&&routeUses(s,r,target)):[];
 return {cost:Math.round(w.cost*worksDiscount(s)),months:w.duration,closes:!!w.closes,affected,label:w.label};
}
function startWork(s,kind,target){
 ensurePlaying(s);const q=workQuote(s,kind,target);spend(s,q.cost);
 const id='w-'+kind+'-'+target+'-'+s.nextId++,name=kind==='changer'?'Cambiador de ancho en '+I.NODES[target].name:q.label+' · '+I.tramoDef(s,target).name;
 s.projects.push({id,type:kind==='changer'?'changer':'tramo',work:kind,target,started:s.month,due:s.month+q.months,originalDue:s.month+q.months,cost:q.cost,done:false,delay:0});
 for(const r of q.affected){r.active=false;r.fleet=null;r.units=0;r.cut=id;}
 if(q.closes)s.reputation=clamp(s.reputation-1-q.affected.length,5,100);
 s.infra.ver++;log(s,'Obra adjudicada',name+(q.affected.length?' · '+q.affected.length+' servicios cortados mientras dure':''));return id;
}
function newLineQuote(a,b){if(!I.NODES[a]||!I.NODES[b]||a===b)throw Error('Elige dos sitios distintos.');const ca=I.NODES[a],cb=I.NODES[b],rad=Math.PI/180;const dlat=(cb.lat-ca.lat)*rad,dlon=(cb.lon-ca.lon)*rad;const hav=Math.sin(dlat/2)**2+Math.cos(ca.lat*rad)*Math.cos(cb.lat*rad)*Math.sin(dlon/2)**2;const km=Math.round(6371*2*Math.asin(Math.sqrt(hav))*1.2);return {km,cost:Math.round(km*1.1+25),duration:Math.round(42+km/10)};}
function buildLine(s,a,b){
 ensurePlaying(s);if(s.infra.custom.length>=40)throw Error('Ya hay 40 líneas propias: termina lo que has empezado.');const q=newLineQuote(a,b);
 if(I.allTramos(s).some(t=>t.kind==='lav'&&((t.a===a&&t.b===b)||(t.a===b&&t.b===a))))throw Error('Ya hay (o habrá) alta velocidad entre esos dos puntos.');
 spend(s,q.cost);const id='lav'+s.nextId++;
 s.infra.custom.push({id,a,b,km:q.km});s.infra.t[id]={g:'std',e:'25kv',v:300,b:false};s.infra.ver++;
 s.projects.push({id,type:'custom',target:id,started:s.month,due:s.month+q.duration,originalDue:s.month+q.duration,cost:q.cost,done:false,delay:0});
 if(CITIES.some(c=>c.id===a)&&CITIES.some(c=>c.id===b)&&!s.routes.some(r=>r.ends.includes(a)&&r.ends.includes(b)))s.routes.push(makeRoute('svc-'+id,[a,b],[a,b],'new',{custom:true}));
 log(s,'Línea nueva adjudicada','LAV '+I.NODES[a].name+' — '+I.NODES[b].name+' · '+q.km+' km.');return id;
}
/** Crea una relación nueva entre dos ciudades; el trazado lo decide la red. */
function createService(s,a,b){
 ensurePlaying(s);
 if(!CITIES.some(c=>c.id===a)||!CITIES.some(c=>c.id===b)||a===b)throw Error('Elige dos ciudades distintas.');
 if(s.routes.some(r=>(r.ends[0]===a&&r.ends[1]===b)||(r.ends[0]===b&&r.ends[1]===a)))throw Error('Esa relación ya existe. Búscala en la lista.');
 if(s.routes.filter(r=>r.custom).length>=40)throw Error('Ya tienes demasiadas relaciones inventadas.');
 const r=makeRoute('svc-'+s.nextId++,[a,b],[a,b],'new',{custom:true});s.routes.push(r);log(s,'Relación nueva en estudio',routeName(r));return r.id;
}
function loan(s,amount){ensurePlaying(s);amount=Number(amount);if(!Number.isFinite(amount)||![100,-100].includes(amount))throw Error('Operación no válida.');if(amount>0&&s.debt+amount>1500)throw Error('El banco ya no te coge el teléfono: tope de 1.500 M€.');if(amount<0&&(s.debt<100||s.cash<100))throw Error('Para amortizar 100 M€ hay que tenerlos, en la caja y en la deuda.');s.cash+=amount;s.debt+=amount;}
function ensurePlaying(s){if(s.ended)throw Error('La campaña ha terminado. Puedes mirar las cuentas o empezar otra.');}
function spend(s,cost){if(!Number.isFinite(cost)||cost<0)throw Error('Importe no válido.');if(s.cash<cost)throw Error('No hay dinero. Ni para eso ni para casi nada: mira Finanzas.');s.cash-=cost;}
function pendingDecision(s){if(!s.started||s.ended)return null;const randomEvent=s.event?{...EVENTS.find(e=>e.id===s.event),event:true}:null;if(s.tycoon.mode==='free')return randomEvent||(s.tycoon.encounter?ENCOUNTER[s.tycoon.encounter]:null);return DECISIONS.find(d=>s.month>=d.at&&!s.decided.includes(d.id))||randomEvent||(s.tycoon.encounter?ENCOUNTER[s.tycoon.encounter]:null);}
/** Imprevisto del mes: sale al azar entre los que encajan con la fecha y lo que está pasando. */
function rollEvent(s){
 if(s.event||s.month<3||(s.tycoon.mode==='campaign'&&s.month>=346)||random(s)>.32)return;
 const recent=new Set((s.events||[]).filter(e=>s.month-e.month<30).map(e=>e.id)),busy=s.projects.some(p=>!p.done&&p.type!=='upgrade');
 const pool=EVENTS.filter(e=>!recent.has(e.id)&&s.month>=(e.from||0)&&(!e.months||e.months.includes(s.month%12))&&(!e.needsWorks||busy));
 if(pool.length)s.event=pool[Math.floor(random(s)*pool.length)].id;
}
function applyEffects(s,c){
 const e=c.effects||{};if((e.cash||0)<0)spend(s,-e.cash);else s.cash+=e.cash||0;
 s.reputation=clamp(s.reputation+(e.reputation||0),5,100);s.satisfaction=clamp(s.satisfaction+(e.satisfaction||0),0,100);
 if(c.policy)s.policy=c.policy;
 if(c.flag==='fleetcare')s.fleet.forEach(f=>f.condition=clamp(f.condition+8,0,100));else if(c.flag)s.flags[c.flag]=s.month+(c.months||{passes:18,rural:60,factory:36,backlog:18}[c.flag]||12);
 if(c.fleet&&MODEL[c.fleet.model])s.fleet.push({id:'f'+s.nextId++,model:c.fleet.model,qty:c.fleet.qty,condition:c.fleet.condition||80,born:yearOf(s)-6,origin:'Segunda mano'});
 if(c.fleetDamage)s.fleet.forEach(f=>f.condition=clamp(f.condition-c.fleetDamage,15,100));
 if(c.worksDelay)for(const p of s.projects)if(!p.done&&p.type!=='upgrade'){p.due=Math.max(s.month+1,p.due+c.worksDelay);if(c.worksDelay>0)p.delay=(p.delay||0)+c.worksDelay;}
 if(c.changer&&!s.infra.c.includes(c.changer)&&I.NODES[c.changer]){s.infra.c.push(c.changer);s.infra.ver++;}
 if(c.gamble){const win=random(s)<c.gamble.chance;applyEffects(s,{effects:win?c.gamble.good:c.gamble.bad});return win;}
 return null;
}
function decide(s,id,index){ensurePlaying(s);const d=pendingDecision(s);if(!d||d.id!==id||!d.choices[index])throw Error('Decisión no disponible.');const c=d.choices[index];
 const win=applyEffects(s,c);
 if(d.tycoon){s.tycoon.encounter=null;if(c.group)s.tycoon.groups[c.group]=clamp(s.tycoon.groups[c.group]+c.trust,0,100);}
 else if(d.event){s.events=[...(s.events||[]),{id,month:s.month}].slice(-60);s.event=null;}else s.decided.push(id);
 log(s,d.title,c.label+(win===true?' · salió bien':win===false?' · salió mal':''));return win;}
const dailyTrains=s=>s.routes.filter(r=>r.active).reduce((n,r)=>n+r.frequency*2,0);
/** Ciudades con un AVE en servicio que llega hasta ellas. */
