function parseMel(str) {
  const out = []; let beat = 0;
  for (const tok of str.trim().split(/\s+/)) { const [n, d] = tok.split(':'); out.push({beat, midi: n === '-' ? null : midi(n), dur: +d}); beat += +d; }
  return {notes: out, beats: beat};
}
