  pickTrain: {p: 2, db: 4, fn: (L) => { L.click({f: 2600, q: 3, dur: .008, v: .22}); L.click({t: .022, f: 2600, q: 3, dur: .008, v: .18}); L.smp('ui_tri', {k: 1, t: .02, v: .1, rate: 1.25, hp: 2000, dur: .3}); L.smp('ui_vibe', {m: 88, t: .03, v: .07, dur: .35}); }},
