  tutorialNext: {p: 2, db: 2, fn: (L, o) => { L.smp('ui_paper', {v: .07, hp: 2000, dur: .1}); L.smp('ui_vibe', {m: deg((o.i ?? 0) % 7), t: .02, v: .11, dur: .6}); }},
